from fractions import Fraction

def solve2(matrix, rhs):
    if type(matrix) is not list or len(matrix) != 2 or any(type(row) is not list or len(row) != 2 for row in matrix):
        raise ValueError("expected 2x2 list matrix")
    if type(rhs) is not list or len(rhs) != 2:
        raise ValueError("expected length2 RHS list")
    values = [v for row in matrix for v in row] + rhs
    if any(type(v) not in (int,Fraction) for v in values):
        raise ValueError("expected exact int/Fraction entries, excluding bool")
    values = [Fraction(v) for v in values]
    if any(abs(v.numerator) > 1000000000 or v.denominator > 1000000 for v in values):
        raise ValueError("entry outside exact teaching bounds")
    rows = [[values[0],values[1],values[4]], [values[2],values[3],values[5]]]
    if abs(rows[1][0]) > abs(rows[0][0]):
        rows[0], rows[1] = rows[1], rows[0]
    if rows[0][0] == 0:
        raise ValueError("singular: no unique solution")
    multiplier = rows[1][0] / rows[0][0]
    rows[1] = [b-multiplier*a for a,b in zip(rows[0],rows[1])]
    if rows[1][1] == 0:
        raise ValueError("singular: no unique solution")
    x1 = rows[1][2] / rows[1][1]
    x0 = (rows[0][2]-rows[0][1]*x1) / rows[0][0]
    return [x0,x1]

matrix, rhs = [[0,2],[1,3]], [4,7]
solution = solve2(matrix,rhs)
print([str(x) for x in solution])
print([str(b-sum(a*x for a,x in zip(row,solution))) for row,b in zip(matrix,rhs)])
print(matrix)
try:
    solve2([[1,2],[2,4]], [3,6])
except ValueError:
    print("singular system rejected")
